/* MochiPay ON_SITE sandbox presentation 82.86. No API credentials or live transfers. */
(function (global) {
    'use strict';
    var proofPattern = /^SANDBOX0[a-f0-9]{32}$/;
    function isSandbox(address) { return proofPattern.test(String(address || '')); }
    function destination(data) {
        try {
            var base = new URL(String(data.sandboxApiBase || ''));
            var hpp = new URL(String(data.sandboxHppUrl || ''));
            if (base.protocol !== 'https:' || base.username || base.password || base.search || base.hash ||
                hpp.protocol !== 'https:' || hpp.origin !== base.origin || hpp.username || hpp.password ||
                hpp.search || hpp.hash || !/^\/pay\/[a-f0-9]{32}$/.test(hpp.pathname)) return null;
            return {url: base.origin + '/Api/SandboxSimulate.aspx', hpp: hpp.href, id: hpp.pathname.slice(5)};
        } catch (e) { return null; }
    }
    function node(tag, text, className) {
        var item = document.createElement(tag);
        if (text) item.textContent = text;
        if (className) item.className = className;
        return item;
    }
    function refresh(root) {
        // The original poller performs authenticated server verification and its normal redirect.
        var button = root.querySelector('.mp-refresh, #refresh');
        if (button && !button.disabled) button.click();
    }
    function update(qr, data) {
        var root = qr.closest('[data-mp-compact]');
        if (!root) return;
        var sandbox = isSandbox(data.address);
        root.classList.toggle('mp-sandbox-checkout', sandbox);
        var old = root.querySelector('.mp-sandbox-panel');
        if (!sandbox) { if (old) old.hidden = true; return; }
        var target = destination(data), state = root._mpSandbox;
        if (!state) {
            var panel = node('section', '', 'mp-sandbox-panel');
            panel.setAttribute('aria-label', 'Sandbox test');
            panel.appendChild(node('strong', 'Sandbox test', 'mp-sandbox-badge'));
            panel.appendChild(node('p', 'Simulation only. Do not send real funds.', 'mp-sandbox-note'));
            var actions = node('div', '', 'mp-sandbox-actions');
            var paid = node('button', 'Simulate successful payment', 'mp-sandbox-paid'); paid.type = 'button';
            var failed = node('button', 'Simulate failed payment', 'mp-sandbox-failed'); failed.type = 'button';
            actions.appendChild(paid); actions.appendChild(failed); panel.appendChild(actions);
            var message = node('p', '', 'mp-sandbox-message'); message.setAttribute('role', 'status');
            message.setAttribute('aria-live', 'polite'); panel.appendChild(message);
            var fallback = node('a', 'Open test checkout', 'mp-sandbox-fallback');
            fallback.target = '_blank'; fallback.rel = 'noopener noreferrer'; fallback.hidden = true;
            panel.appendChild(fallback);
            var details = root.querySelector('.mp-details, #details');
            if (!details) return;
            details.insertBefore(panel, details.firstChild);
            state = root._mpSandbox = {panel: panel, paid: paid, failed: failed, message: message,
                fallback: fallback, pending: false, submitted: false, address: ''};
            paid.addEventListener('click', function () { simulate(root, state, 'paid'); });
            failed.addEventListener('click', function () { simulate(root, state, 'failed'); });
        }
        if (state.address !== data.address) {
            state.pending = false; state.submitted = false; state.message.textContent = '';
        }
        state.address = data.address; state.target = target; state.panel.hidden = false;
        state.status = String(data.status || '').toUpperCase();
        var waiting = ['WAITING', 'WAITING_PAYMENT', 'PENDING'].indexOf(state.status) !== -1;
        var blocked = !target || !waiting || state.pending || state.submitted;
        state.paid.disabled = blocked; state.failed.disabled = blocked;
        if (target) { state.fallback.href = target.hpp; state.fallback.hidden = false; }
        else {
            state.fallback.removeAttribute('href'); state.fallback.hidden = true;
            state.message.textContent = 'Simulation is unavailable. Open the saved hosted checkout or contact the store.';
        }
        if (!waiting && !state.pending) state.message.textContent = 'This test payment is no longer waiting for payment.';
    }
    function simulate(root, state, action) {
        if (!state.target || !isSandbox(state.address) || state.pending || state.submitted ||
            ['WAITING', 'WAITING_PAYMENT', 'PENDING'].indexOf(state.status) === -1) return;
        state.pending = true; state.paid.disabled = true; state.failed.disabled = true;
        state.message.textContent = 'Submitting simulation. Waiting for verified payment status…';
        var requestAddress = state.address, requestTarget = state.target;
        var xhr = new XMLHttpRequest();
        xhr.open('POST', requestTarget.url, true); xhr.timeout = 30000; xhr.withCredentials = false;
        xhr.setRequestHeader('Content-Type', 'application/json'); xhr.setRequestHeader('Accept', 'application/json');
        function failed() {
            if (state.address !== requestAddress) return;
            state.pending = false; state.submitted = false;
            var waiting = ['WAITING', 'WAITING_PAYMENT', 'PENDING'].indexOf(state.status) !== -1;
            state.paid.disabled = !waiting; state.failed.disabled = !waiting;
            state.message.textContent = 'Unable to submit simulation. Try again or open the test checkout.';
        }
        xhr.onload = function () {
            if (state.address !== requestAddress) return;
            try {
                var result = JSON.parse(xhr.responseText);
                if (xhr.status < 200 || xhr.status >= 300 || result.success !== true ||
                    result.status !== (action === 'paid' ? 'PAID' : 'FAILED')) { failed(); return; }
                state.pending = false; state.submitted = true;
                // Never mark an order paid here. Reuse the original verified query/fulfilment path.
                state.message.textContent = 'Simulation submitted. Waiting for verified payment status…';
                global.setTimeout(function () { refresh(root); }, 500);
                global.setTimeout(function () { refresh(root); }, 2000);
            } catch (e) { failed(); }
        };
        xhr.onerror = xhr.ontimeout = failed;
        xhr.send(JSON.stringify({order_id: requestTarget.id, payment_address: requestAddress, action: action}));
    }
    global.MochiPaySandboxUi = {isSandbox: isSandbox, destination: destination, update: update, version: '82.86'};
})(window);

